[YZ_DICE];Xint *score;Xint cat;XX	{X	int new_dice[YZ_DICE];X	int i;XX	for (i = 0; i < YZ_DICE; ++i)X		new_dice[i] = dice[i].dice;X	DICE_SORT(new_dice);X	if ((new_dice[0] == new_dice[1] && new_dice[1] == new_dice[2] &&X	     new_dice[3] == new_dice[4]) ||X	    (new_dice[2] == new_dice[3] && new_dice[3] == new_dice[4] &&X	     new_dice[0] == new_dice[1]))X		*score = SC_FULL_HOUSE;X	}XXstatic void EvStraight(dice, score, cat)XXdice_t dice[YZ_DICE];Xint *score;Xint cat;XX	{X	int new_dice[YZ_DICE];X	int i, j, run, conseq;X	int next;XX	cat -= SC_STRAIGHT_NORMAL;X	for (i = 0; i < YZ_DICE; ++i)X		new_dice[i] = dice[i].dice;X	DICE_SORT(new_dice);X	for (i = 0; i < YZ_DICE - 1; i = j)X		{X		j = i;X		run = 0;X		do	{X			next = j + 1;X			if (conseq = new_dice[j] + 1 == new_dice[next])X				++run;X			if (! conseq)X				conseq = new_dice[j] == new_dice[next];X			++j;X			} while (conseq && j < YZ_DICE - 1);X		if (run >= cat)X			{X			*score = StraightScore[cat - SC_STR_SCORE_NORM];X			return;X			}X		}X	}XXstatic void EvYahtzee(dice, score, cat)XXdice_t dice[YZ_DICE];Xint *score;Xint cat;XX	{X	EvOaK(dice, score, YZ_DICE + SC_OAK_NORMAL);X	if (*score)X		*score = SC_YAHTZEE;X	}XXstatic void EvChance(dice, score, cat)XXdice_t dice[YZ_DICE];Xint *score;Xint cat;XX	{X	int i;XX	for (i = 0; i < YZ_DICE; ++i)X		*score += dice[i].dice + 1;X	}END_OF_FILEif test 3207 -ne `wc -c <'eval.c'`; then    echo shar: \"'eval.c'\" unpacked with wrong size!fi# end of 'eval.c'fiif test -f 'help.c' -a "${1}" != "-c" ; then   echo shar: Will not clobber existing file \"'help.c'\"elseecho shar: Extracting \"'help.c'\" \(2802 characters\)sed "s/^X//" >'help.c' <<'END_OF_FILE'X#include <curses.h>X#include "yz_consts.h"X#include "yz_types.h"X#include "yz_macros.h"X#include "yz_funcs.h"XXstatic char *Also[] = {X	"Also press:",X	"   '?'  - for help any time",X	"   's'  - current scores",X	"   'b'  - display rules",X	"  